def gen(rng):
    def build(n, parent_fn, st=None):
        perm = list(range(n))
        rng.shuffle(perm)
        edges = []
        for i in range(1, n):
            a, b = perm[i], perm[parent_fn(i)]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append((a, b))
        rng.shuffle(edges)
        if st is None:
            s, t = rng.randrange(n), rng.randrange(n)
        else:
            s, t = perm[st[0]], perm[st[1]]
        lines = [str(n)] + [f'{a} {b}' for a, b in edges] + [f'{s} {t}']
        return '\n'.join(lines)
    tests = [
        '1\n0 0',
        '2\n0 1\n0 1',
        '2\n1 0\n1 1',
        '7\n0 1\n0 2\n1 3\n1 4\n2 5\n5 6\n3 6',
        '7\n0 1\n0 2\n1 3\n1 4\n2 5\n5 6\n4 1',
        '5\n0 1\n0 2\n0 3\n0 4\n4 2',
    ]
    for n in (2, 3, 4, 5, 6, 8, 10, 15, 25, 40):
        for _ in range(3):
            mode = rng.random()
            if mode < 0.4:
                tests.append(build(n, lambda i: rng.randint(0, i - 1)))
            elif mode < 0.7:
                tests.append(build(n, lambda i: i - 1))
            else:
                tests.append(build(n, lambda i: 0))
    N = 10**5
    tests.append(build(N, lambda i: rng.randint(0, i - 1)))
    tests.append(build(N, lambda i: 0))
    tests.append(build(5000, lambda i: i - 1, (0, 4999)))
    L = 4800
    tests.append(build(N, lambda i: i - 1 if i < L else rng.randint(0, i - 1), (0, N - 1)))
    return tests
